from collections import Counter

class Solution:
    def uniqueOccurrences(self, arr: list[int]) -> bool:
        counts = Counter(arr).values()
        return len(counts) == len(set(counts))

class Solution {
public:
    bool uniqueOccurrences(std::vector<int>& arr) {
        std::unordered_map<int, int> counts;
        for (int x : arr) counts[x]++;
        std::unordered_set<int> uniqueCounts;
        for (const auto& [val, cnt] : counts) {
            if (!uniqueCounts.insert(cnt).second) return false;
        }
        return true;
    }
};

class Solution {
    public boolean uniqueOccurrences(int[] arr) {
        java.util.Map<Integer, Integer> counts = new java.util.HashMap<>();
        for (int x : arr) counts.put(x, counts.getOrDefault(x, 0) + 1);
        java.util.Set<Integer> uniqueCounts = new java.util.HashSet<>(counts.values());
        return uniqueCounts.size() == counts.size();
    }
}

var uniqueOccurrences = function(arr) {
    const counts = new Map();
    for (const x of arr) counts.set(x, (counts.get(x) || 0) + 1);
    const set = new Set(counts.values());
    return set.size === counts.size;
};
